  (v + 8 + zlength nm <= lo \/ bv_unsigned sp <= v) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  v mod 8 = 0 -> accessible m v (8 + zlength nm) -> accessible m kp (zlength k) -> ACONST m ->
  evt asegs (kcmp1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc k nm lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz kp) (wz (zlength k)) (wz v) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_KEY_COMPARE_SV_VT) fc None m (seg_rom asegs)).

