(* [comment removed for export] *)
(* [comment removed for export] *)
Definition kcmp2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (nm k : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (kc_res nm k)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ ACONST m'.

Definition kcmp2_stmt : Prop := forall (v kp : Z) (nm k : list byte) (rest : list cell) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at asegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  bytes_at asegs m kp k -> zlength k < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + KCMP_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) ->
  (v + 8 + zlength nm <= lo \/ bv_unsigned sp <= v) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  v mod 8 = 0 -> accessible m v (8 + zlength nm) -> accessible m kp (zlength k) -> ACONST m ->
  evt asegs (kcmp2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc nm k lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz v) (wz kp) (wz (zlength k)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_KEY_COMPARE_VT_SV) fc None m (seg_rom asegs)).

Section KCmp2.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (kp v : Z) (k nm : list byte) (lo : Z) (j8 : list byte).
  Hypothesis LO : lo + KCMP_STACK <= bv_unsigned sp.
  Hypothesis HC : aceil <= lo.

  (* [comment removed for export] *)
  Lemma kcmp2_exit : forall m1 (x1 x5 x6 x7 a0 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word) (r : Z),
    kcmp1_ctx ra sp m kp v k nm lo j8 m1 -> r = kc_res nm k ->
    evt asegs (kcmp2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc nm k lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0 s1 a0 (wz r) a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
