  Lemma kcmp2_chk : forall (Q : machine_state -> Prop) (i : nat) (bk bn : byte) m1
      (x1 spx x5 x6 x7 a1 a3 a5 x28 x29 x30 x31 : word),
    bytes_at asegs m1 kp k -> bytes_at asegs m1 (v + 8) nm ->
    accessible m1 kp (zlength k) -> accessible m1 (v + 8) (zlength nm) ->
    nth_error k i = Some bk -> nth_error nm i = Some bn ->
    (forall t0' , evt asegs Q
       (MS (mkR x1 spx gp tp t0' (wz (zb bk)) x7 s0 s1 (wz (v + 8 + Z.of_nat i)) (wz (zb bn)) (wz (kp + Z.of_nat i)) a3 (Z_to_bv 64 2147450880)
                 a5 (wz (v + 8 + Z.of_nat i)) (wz (kp + Z.of_nat i))
                 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
           F (Z_to_bv 64 0xbb80c) fc None m1 (seg_rom asegs))) ->
    evt asegs Q
      (MS (mkR x1 spx gp tp x5 x6 x7 s0 s1 (wz (v + 8 + Z.of_nat i)) a1 (wz (kp + Z.of_nat i)) a3 (Z_to_bv 64 2147450880)
                a5 (wz (v + 8 + Z.of_nat i)) (wz (kp + Z.of_nat i))
                s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 0xbb7e4) fc None m1 (seg_rom asegs)).
