  (* [comment removed for export] *)
  Lemma kcmp2_loop : forall (cnt i : nat) m1 (x1 x5 x6 x7 a1 x28 x29 x30 x31 : word),
    (cnt = length nm - i)%nat -> (i < length nm)%nat -> length k = length nm ->
    ilex (zbytes nm) (zbytes k) = ilex (zbytes (skipn i nm)) (zbytes (skipn i k)) ->
    kcmp1_ctx ra sp m kp v k nm lo j8 m1 -> zlength k < 2^64 -> zlength nm + 2 < 2^16 ->
    evt asegs (kcmp2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc nm k lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0 s1 (wz (v + 8 + Z.of_nat i)) a1 (wz (kp + Z.of_nat i))
                (wz (zlength nm - 1 - Z.of_nat i)) (Z_to_bv 64 2147450880) (wz (zlength nm - Z.of_nat i)) (wz (v + 8 + Z.of_nat i))
                (wz (kp + Z.of_nat i))
                s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
