(* [comment removed for export] *)

(* [comment removed for export] *)
Definition ITTO_STACK : Z := 16.

Definition itto_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res e lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' res [C8 (wz e)]
    /\ ACONST m'.

Definition itto_stmt (entry : Z) : Prop := forall (res e nxt lo : Z) (rest : list cell) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m e (C8 (wz nxt) :: rest) -> 0 < nxt < 2^64 ->
  rw_cells asegs m res [CB 8 rj] ->
  stk asegs m lo (bv_unsigned sp) -> lo + ITTO_STACK <= bv_unsigned sp -> aceil <= lo ->
  (e + Z.of_nat (cells_size (C8 (wz nxt) :: rest)) <= bv_unsigned sp - 16 \/ bv_unsigned sp <= e) ->
  (res + 8 <= bv_unsigned sp - 16 \/ bv_unsigned sp <= res) ->
  (e + Z.of_nat (cells_size (C8 (wz nxt) :: rest)) <= res \/ res + 8 <= e) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  e mod 8 = 0 -> accessible m e 8 -> res mod 8 = 0 -> accessible m res 8 -> awin (res, res + 8) -> ACONST m ->
  evt asegs (itto_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc res e lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) a1 (wz e) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 entry) fc None m (seg_rom asegs)).

Local Ltac itto_tac :=
  intros res e nxt lo rest rj ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m;
  intros EC0 NX RC ST LO HC SEP1 SEP2 SEP3 MI EAL EAC RAL RAC RWIN AC;
  cbn [cells_size csize] in SEP1, SEP3;
  let EC := fresh "EC" in let ECB := fresh "ECB" in
  pose proof (proj1 (proj1 (rw_cells_app asegs m e [C8 (wz nxt)] rest) EC0)) as EC; clear EC0;
  pose proof (rw_cells_bound _ _ _ _ EC) as ECB; cbn [cells_size csize Nat.add] in ECB;
  pose proof (rw_cells_bound _ _ _ _ RC) as RCB; cbn [cells_size csize Nat.add] in RCB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (munch_refl [(lo, bv_unsigned sp); (res, res + 8)]%Z m) as MU; pose proof (wmono_refl asegs m) as WM;
  pose proof (ACONST_shbase _ AC) as [G1 G2]; unfold AGOT_SHBASE, ASHBASE_CELL, wz in G1, G2; rewrite ASHADOW_BASE_val in G2;
  unfold ITTO_STACK, wz in *;
  assert (FW : Forall awin [(lo, bv_unsigned sp); (res, res + 8)]%Z)
    by (repeat apply Forall_cons; [apply awin_stack; lia| exact RWIN| apply Forall_nil]);
  carve_frame 16%nat ST;
  (* [comment removed for export] *)
  step; st1; st1; step; step; step; clear G1 G2;
  (* [comment removed for export] *)
  let RD := fresh "RD" in
  lazymatch goal with MUx : munch _ m ?mx |- _ =>
    pose proof (accessible_read0_sr mx e 8 e (accessible_transport_awin _ _ _ _ _ EAC MUx FW) ltac:(lia) EAL ltac:(lia)) as RD end;
  shchk_fast RD;
  step; step;
  let K := fresh "K" in
  if_cases K; zify_cond K; [exfalso; lia|];
  (* [comment removed for export] *)
  let RD2 := fresh "RD" in
  lazymatch goal with MUx : munch _ m ?mx |- _ =>
    pose proof (accessible_read0_sr mx res 8 res (accessible_transport_awin _ _ _ _ _ RAC MUx FW) ltac:(lia) RAL ltac:(lia)) as RD2 end;
  shchk_fast RD2;
  st1;
  (* [comment removed for export] *)
  step; step; step;
  lazymatch goal with
  | FR : rw_cells _ _ (bv_unsigned sp + -16) _, ST' : stk _ _ lo _ |- _ => release_frame FR ST' (bv_unsigned sp)
  end;
  step;
  lazymatch goal with MUx : munch _ m ?mx, WMx : wmono _ m ?mx |- _ =>
